// Package cnfrt is the runtime support library for code generated by
// cmd/cnfgo.
//
// It provides the pointer-free building blocks of cnfgo snapshots
// (NodeID, Span32, VariantTag), deterministic hashing, lossless codecs for
// time.Time and net/netip values, the two-pass arena builder used by
// generated Freeze functions, the immutable FrozenMap and mutable SlabMap
// hash tables, the .cnf binary container format, and a leak detector for
// retired snapshots.
//
// Package cnfrt (together with package unsafemmap) is the only place where
// cnfgo uses package unsafe. Generated code never imports unsafe.
package cnfrt

import (
	"errors"
	"math"
)

// NodeID is a 1-based index into a typed node table. The zero NodeID
// represents a nil reference.
type NodeID uint32

// IsNil reports whether id is the nil reference.
func (id NodeID) IsNil() bool { return id == 0 }

// NilSpanOff is the Span32.Off sentinel that marks a nil slice, nil map or
// nil byte slice. A non-nil empty value is encoded as Span32{Off: 0, Len: 0}.
const NilSpanOff = math.MaxUint32

// Span32 addresses a contiguous run of elements (or bytes) inside a pool.
type Span32 struct {
	Off uint32
	Len uint32
}

// NilSpan is the canonical encoding of a nil slice or map.
var NilSpan = Span32{Off: NilSpanOff, Len: 0}

// IsNil reports whether s encodes a nil slice or map.
func (s Span32) IsNil() bool { return s.Off == NilSpanOff }

// IsDict reports whether s addresses a string stored in a shared Dict.
func (s Span32) IsDict() bool { return s.Off&DictSpanBit != 0 && s.Len > 0 }

// End returns the exclusive end offset of s as a uint64, which cannot
// overflow.
func (s Span32) End() uint64 { return uint64(s.Off) + uint64(s.Len) }

// InBounds reports whether s is either nil (with zero length) or lies
// completely within [0, n).
func (s Span32) InBounds(n int) bool {
	if s.Off == NilSpanOff {
		return s.Len == 0
	}
	return s.End() <= uint64(n)
}

// VariantTag encodes a value of a closed interface type: Tag is the 1-based
// index of the dynamic type in the interface's implementation list (0 means
// a nil interface) and ID is the NodeID of the value in that type's table.
type VariantTag struct {
	Tag uint16
	Pad uint16
	ID  uint32
}

// IsNil reports whether v encodes a nil interface value.
func (v VariantTag) IsNil() bool { return v.Tag == 0 }

// VerifyMode selects how much validation is performed when a .cnf image is
// opened.
type VerifyMode uint8

const (
	// VerifyTrustedHeader validates the header, header and directory
	// checksums, schema hash and section geometry (bounds and alignment).
	// Section payloads are not read, so opening a memory-mapped file costs
	// microseconds regardless of its size. Corrupt payloads can cause
	// bounds-check panics in accessors but never out-of-bounds reads.
	VerifyTrustedHeader VerifyMode = iota
	// VerifyChecksum additionally verifies the CRC32C of every section.
	VerifyChecksum
	// VerifyUntrusted copies the image into the Go heap (so later external
	// modification of the file cannot affect the snapshot), verifies all
	// checksums and validates every NodeID, Span32, VariantTag, location and
	// zone index, and the acyclicity invariant (childID > selfID) of
	// snapshots without FlagCyclicAllowed. Accessors on a snapshot opened in
	// this mode cannot panic.
	VerifyUntrusted
)

// String returns the name of the verification mode.
func (m VerifyMode) String() string {
	switch m {
	case VerifyTrustedHeader:
		return "VerifyTrustedHeader"
	case VerifyChecksum:
		return "VerifyChecksum"
	case VerifyUntrusted:
		return "VerifyUntrusted"
	}
	return "VerifyMode(invalid)"
}

// Errors reported by cnfrt and by generated code.
var (
	// ErrCycleDetected is returned when a directed cycle is found in a graph
	// passed to Freeze or FreezeTree, or when FreezeTree exceeds its maximum
	// depth.
	ErrCycleDetected = errors.New("cnfrt: cycle detected in object graph")
	// ErrCapacityExceeded is returned when a table, pool, string blob or
	// side table exceeds the limits of the 32-bit encoding.
	ErrCapacityExceeded = errors.New("cnfrt: capacity of 32-bit encoding exceeded")
	// ErrNaNKey is returned when a NaN floating-point value is used as (or
	// inside) a hash or sorted map key.
	ErrNaNKey = errors.New("cnfrt: NaN map key")
	// ErrCorruptHeader is returned when a .cnf header or section directory
	// is malformed.
	ErrCorruptHeader = errors.New("cnfrt: corrupt .cnf header")
	// ErrSchemaMismatch is returned when a .cnf image was produced for a
	// different schema than the one used to open it.
	ErrSchemaMismatch = errors.New("cnfrt: .cnf schema hash mismatch")
	// ErrChecksumMismatch is returned when a section checksum does not
	// match its payload.
	ErrChecksumMismatch = errors.New("cnfrt: .cnf checksum mismatch")
	// ErrBoundsViolation is returned when an index or span in a .cnf image
	// points outside its target table or pool, or spans overlap.
	ErrBoundsViolation = errors.New("cnfrt: .cnf bounds violation")
	// ErrMmapFault is returned by fault-safe helpers when a memory access to
	// a mapped file faults, typically because the file was truncated.
	ErrMmapFault = errors.New("cnfrt: fault while reading memory-mapped snapshot")
	// ErrUnsupportedType is returned when a value of a type that cannot be
	// encoded is encountered at run time, such as an unregistered dynamic
	// type stored in a closed interface.
	ErrUnsupportedType = errors.New("cnfrt: unsupported type")
	// ErrClosed is returned when a closed snapshot or map is used.
	ErrClosed = errors.New("cnfrt: use of closed snapshot")
	// ErrConcurrentModification is returned when the source graph changes
	// between the two passes of Freeze.
	ErrConcurrentModification = errors.New("cnfrt: source graph modified during Freeze")
	// ErrUnknownDict is returned when a value references a shared Dict that
	// is closed or not open in the current process, and when Pack or Freeze
	// is called with a closed Dict.
	ErrUnknownDict = errors.New("cnfrt: unknown or closed string dictionary")
	// ErrDictRequired is returned when a value backed by an in-process Dict
	// is serialized to a standalone .cnf image without detaching it, and
	// when VerifyUntrusted meets a value that references a Dict without the
	// matching AllowDict option.
	ErrDictRequired = errors.New("cnfrt: value uses an in-process Dict that was not provided")
)

// DictUser is implemented by values that may reference strings in a
// process-local Dict, such as generated snapshots and Compact values.
// FrozenMap.WriteTo refuses to persist values for which UsesDict reports
// true.
type DictUser interface {
	UsesDict() bool
}

// SchemaHasher is implemented by generated Compact values. FrozenMapSchema
// includes the schema hash of such value types, so that a persisted map is
// rejected when the layout of its values changes.
type SchemaHasher interface {
	SchemaHashCNF() uint64
}

// Abort carries an error out of deeply recursive generated code. Generated
// Freeze functions call Fail to abort and recover the Abort value at their
// entry point.
type Abort struct{ Err error }

// Fail aborts the current freeze operation with err.
func Fail(err error) { panic(Abort{Err: err}) }

// Recover converts a panic raised by Fail into an error stored in *err. Any
// other panic is propagated. It must be called directly by a deferred
// function.
func Recover(r any, err *error) {
	if r == nil {
		return
	}
	if a, ok := r.(Abort); ok {
		*err = a.Err
		return
	}
	panic(r)
}

// CheckLen32 aborts the current freeze with ErrCapacityExceeded unless n can
// be represented as a 32-bit length that is also safe on 32-bit platforms.
func CheckLen32(n int) uint32 {
	if n < 0 || uint64(n) > MaxElems {
		Fail(ErrCapacityExceeded)
	}
	return uint32(n)
}

// MaxElems is the maximum number of elements in a table or pool. It leaves
// room for NilSpanOff and keeps every byte offset representable as int on
// 32-bit platforms for the element sizes used in practice.
const MaxElems = math.MaxUint32 - 1

// MaxBlob is the maximum size in bytes of a string blob and of the raw
// encoding of a Compact value, so that i+8 never overflows int on 32-bit
// platforms.
const MaxBlob = math.MaxInt32 - 64
